> +++ b/drivers/misc/fastrpc.c
> @@ -365,7 +365,8 @@ static void fastrpc_free_map(struct kref *ref)
>  
>  	if (map->fl) {
>  		spin_lock(&map->fl->lock);
> -		list_del(&map->node);
> +		if (!list_empty(&map->node))
